package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseN2MigrationTest extends MigrationTestSupport {
 @Test void populatedN1ReservationSurvivesQueueUpgradeWithoutInventingCoverage(){String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_n2_upgrade_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("53").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));
  try{UUID member=db.queryForObject("INSERT INTO users(email,password_hash,status,email_verified) VALUES('n2-member@example.test','synthetic-only','ACTIVE',TRUE) RETURNING id",UUID.class),listener=db.queryForObject("INSERT INTO users(email,password_hash,status,email_verified) VALUES('n2-listener@example.test','synthetic-only','ACTIVE',TRUE) RETURNING id",UUID.class),rule=UUID.randomUUID(),booking=UUID.randomUUID();db.update("INSERT INTO listener_calendar_rules(id,listener_id,timezone,weekday,starts_local,ends_local,valid_from,valid_until,overlap_policy) VALUES(?,?,'UTC',1,'09:00','12:00',CURRENT_DATE,CURRENT_DATE+14,'EARLIER')",rule,listener);db.update("INSERT INTO listener_bookings(id,member_id,listener_id,client_key,rule_id,timezone,starts_at,ends_at,reserved_until) SELECT ?,?,?,?,?,'UTC',t.at,t.at+INTERVAL '30 minutes',t.at+INTERVAL '37 minutes 30 seconds' FROM(SELECT (date_trunc('week',CURRENT_TIMESTAMP AT TIME ZONE 'UTC') AT TIME ZONE 'UTC')+INTERVAL '7 days 10 hours' AS at)t",booking,member,listener,UUID.randomUUID(),rule);var before=db.queryForList("SELECT * FROM listener_bookings");var rules=db.queryForList("SELECT * FROM listener_calendar_rules");var f=Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load();f.migrate();f.validate();assertThat(db.queryForList("SELECT * FROM listener_bookings")).isEqualTo(before);assertThat(db.queryForList("SELECT * FROM listener_calendar_rules")).isEqualTo(rules);assertThat(db.queryForObject("SELECT count(*) FROM listener_wait_queue",Integer.class)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM listener_queue_coverage_windows",Integer.class)).isZero();
  }finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}
 }
}
